Given a string s, the task is to find the minimum number of characters to be inserted to convert it to a palindrome.Examples:Input: s = "geeks"Output: 3Explanation: "skgeegks" is a palindromic string, which requires 3 insertions.Input: s= "abcd"Output: 3Explanation: "abcdcba" is a palindromic string.Input: s= "aba"Output: 0Explanation: Given string is already a palindrome hence no insertions are required.Try It YourselfTable of ContentUsing Recursion - O(2^n) Time and O(n) SpaceUsing Top-Down DP (Memoization) - O(n^2) Time and O(n^2) SpaceUsing Bottom-Up DP (Tabulation) - O(n^2) Time and O(n^2) SpaceUsing Space Optimized DP – O(n ^ 2) Time and O(n) SpaceUsing Recursion - O(2^n) Time and O(n) SpaceLet minimum number of insertions in the string str[l…..h] be  findMinInsertions(str[l…..h]). It can be recursively defined as.if str[l] is equal to str[h], then findMinInsertions(str[l+1…..h-1]) Else min(findMinInsertions(str[l…..h-1]), findMinInsertions(str[l+1…..h])) + 1 
            C++

    // C++ approach to find Minimum 
// insertions to form a palindrome
#include<bits/stdc++.h>
using namespace std;

// Recursive function to find  
// minimum number of insertions
int minRecur(string &s, int l, int h) {

  	// Base case
    if (l >= h) return 0;

  	// if first and last char are same 
  	// then no need to insert element
  	if(s[l] == s[h]) {
      	return minRecur(s, l + 1, h - 1);
    }

  	// Insert at begining or insert at end
  	return min(minRecur(s, l + 1, h), 
               minRecur(s, l, h - 1)) + 1;
}

int findMinInsertions(string &s) {
 	return minRecur(s, 0, s.size() - 1);
}

int main() {
    string s = "geeks";
    cout << findMinInsertions(s);
    return 0;
}


